#include <iostream>
#include <string>
using namespace std;

struct Record {
    int id;
    string name;
};

const int MAX = 10;

void addRecord(Record list[], int &n);
void showAll(const Record list[], int n);

int main() {
    Record list[MAX];
    int n = 0;
    int choice;
    do {
        cout << "1. Add  2. Show  3. Quit" << endl;
        cout << "Choice: ";
        cin >> choice;
        switch (choice) {
            case 1: addRecord(list, n); break;
            case 2: showAll(list, n); break;
            case 3: cout << "Bye!" << endl; break;
            default: cout << "Invalid choice" << endl;
        }
    } while (choice != 3);
    return 0;
}

void addRecord(Record list[], int &n) {
    if (n == MAX) {
        cout << "List is full" << endl;
        return;
    }
    cout << "ID: ";
    cin >> list[n].id;
    cout << "Name: ";
    cin >> list[n].name;
    n++;
}

void showAll(const Record list[], int n) {
    for (int i = 0; i < n; i++) {
        cout << list[i].id << " " << list[i].name << endl;
    }
}

#include <iostream>
#include <string>
using namespace std;

struct Record {
    int id;
    string name;
};

int findById(const Record list[], int n, int id);

int main() {
    Record list[3] = {{101, "Ali"}, {102, "Sara"}, {103, "Hina"}};
    int id;
    cout << "Search ID: ";
    cin >> id;
    int pos = findById(list, 3, id);
    if (pos == -1) {
        cout << "Not found" << endl;
    } else {
        cout << "Found: " << list[pos].name << endl;
    }
    return 0;
}

int findById(const Record list[], int n, int id) {
    for (int i = 0; i < n; i++) {
        if (list[i].id == id) {
            return i;
        }
    }
    return -1;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

struct Record {
    int id;
    string name;
    double value;
};

const int MAX = 100;

void addRecord(Record list[], int &n);
void showAll(const Record list[], int n);
void searchRecord(const Record list[], int n);
void saveToFile(const Record list[], int n);
void loadFromFile(Record list[], int &n);

int main() {
    Record list[MAX];
    int n = 0;
    int choice;
    loadFromFile(list, n);
    do {
        cout << "\n1. Add  2. Show All  3. Search  4. Save & Exit\nChoice: ";
        cin >> choice;
        switch (choice) {
            case 1: addRecord(list, n); break;
            case 2: showAll(list, n); break;
            case 3: searchRecord(list, n); break;
            case 4: saveToFile(list, n); cout << "Saved. Bye!" << endl; break;
            default: cout << "Invalid choice" << endl;
        }
    } while (choice != 4);
    return 0;
}

void addRecord(Record list[], int &n) {
    if (n >= MAX) {
        cout << "List is full" << endl;
        return;
    }
    cout << "ID: ";
    cin >> list[n].id;
    cout << "Name: ";
    cin >> list[n].name;
    cout << "Value: ";
    cin >> list[n].value;
    n++;
    cout << "Added." << endl;
}

void showAll(const Record list[], int n) {
    if (n == 0) {
        cout << "No records yet." << endl;
        return;
    }
    for (int i = 0; i < n; i++) {
        cout << list[i].id << " " << list[i].name << " " << list[i].value << endl;
    }
}

void searchRecord(const Record list[], int n) {
    int id;
    cout << "Search ID: ";
    cin >> id;
    for (int i = 0; i < n; i++) {
        if (list[i].id == id) {
            cout << "Found: " << list[i].name << endl;
            return;
        }
    }
    cout << "Not found" << endl;
}

void saveToFile(const Record list[], int n) {
    ofstream out("records.txt");
    if (!out) {
        cout << "Cannot save the file" << endl;
        return;
    }
    out << n << endl;
    for (int i = 0; i < n; i++) {
        out << list[i].id << " " << list[i].name << " " << list[i].value << endl;
    }
}

void loadFromFile(Record list[], int &n) {
    ifstream in("records.txt");
    if (!in) {
        return;
    }
    if (!(in >> n) || n > MAX) {
        n = 0;
        return;
    }
    for (int i = 0; i < n; i++) {
        in >> list[i].id >> list[i].name >> list[i].value;
    }
}

